import {test} from 'node:test'
import assert from 'node:assert/strict'
import {inspectUploadSession} from './check-upload-session.mjs'
test('only initializes one unattached manifest, exposes no token and reports expiry',async()=>{let calls=0;const jwt='header.'+Buffer.from(JSON.stringify({exp:4600,nbf:900,secret:'HIDDEN'})).toString('base64url')+'.signature';const r=await inspectUploadSession({token:'SECRET',accountId:'ACCOUNT',now:1000000,fetcher:async(url,options)=>{calls++;assert.ok(url.endsWith('/assets-upload-session'));assert.equal(options.method,'POST');assert.equal(Object.values(JSON.parse(options.body).manifest)[0].size,0);return Response.json({success:true,result:{jwt,buckets:[['hash']]}})}});assert.equal(calls,1);assert.equal(r.remainingSeconds,3600);assert.equal(r.notBeforeSeconds,-100);assert.ok(!JSON.stringify(r).includes('SECRET'));assert.ok(!JSON.stringify(r).includes('HIDDEN'));assert.ok(!JSON.stringify(r).includes(jwt))})
test('denial is not retried',async()=>{let n=0;const r=await inspectUploadSession({token:'x',accountId:'y',fetcher:async()=>{n++;return Response.json({success:false,errors:[{code:10000}]},{status:403})}});assert.equal(n,1);assert.equal(r.ok,false)})
